// =====================================================================
// JOB SOURCES CONFIG  --  EDIT THIS LIST TO ADD / REMOVE COMPANIES
// ---------------------------------------------------------------------
// Only official, public, documented job-board APIs are used (no scraping,
// no login, no CAPTCHA bypass):
//   greenhouse -> https://boards-api.greenhouse.io/v1/boards/<slug>/jobs
//   lever      -> https://api.lever.co/v0/postings/<slug>?mode=json
//   ashby      -> https://api.ashbyhq.com/posting-api/job-board/<slug>
// To add a company: find its careers page, check which ATS it uses
// (URL contains greenhouse.io / lever.co / ashbyhq.com) and copy the slug.
//   enabled          : false = skip this source
//   pollEveryMinutes : poll big boards less often to stay light & polite
// =====================================================================
const SOURCES = [
  // ---- Greenhouse ----
  { company: 'InMobi',     type: 'greenhouse', slug: 'inmobi',     enabled: true, pollEveryMinutes: 1 },
  { company: 'HackerRank', type: 'greenhouse', slug: 'hackerrank', enabled: true, pollEveryMinutes: 1 },
  { company: 'Groww',      type: 'greenhouse', slug: 'groww',      enabled: true, pollEveryMinutes: 1 },
  { company: 'Druva',      type: 'greenhouse', slug: 'druva',      enabled: true, pollEveryMinutes: 2 },
  { company: 'Rubrik',     type: 'greenhouse', slug: 'rubrik',     enabled: true, pollEveryMinutes: 3 },
  { company: 'Sumo Logic', type: 'greenhouse', slug: 'sumologic',  enabled: true, pollEveryMinutes: 2 },
  { company: 'Twilio',     type: 'greenhouse', slug: 'twilio',     enabled: true, pollEveryMinutes: 3 },
  { company: 'Okta',       type: 'greenhouse', slug: 'okta',       enabled: true, pollEveryMinutes: 5 },
  { company: 'GitLab',     type: 'greenhouse', slug: 'gitlab',     enabled: true, pollEveryMinutes: 5 },
  { company: 'MongoDB',    type: 'greenhouse', slug: 'mongodb',    enabled: true, pollEveryMinutes: 5 },
  // ---- Lever ----
  { company: 'CRED',       type: 'lever', slug: 'cred',       enabled: true,  pollEveryMinutes: 1 },
  { company: 'Zeta',       type: 'lever', slug: 'zeta',       enabled: true,  pollEveryMinutes: 3 },
  { company: 'Mindtickle', type: 'lever', slug: 'mindtickle', enabled: true,  pollEveryMinutes: 2 },
  { company: 'Paytm',      type: 'lever', slug: 'paytm',      enabled: false, pollEveryMinutes: 15 }, // very large board (~2.7 MB)
  // ---- Ashby ----
  { company: 'Sarvam AI',  type: 'ashby', slug: 'sarvam', enabled: true, pollEveryMinutes: 1 },
  { company: 'Atlan',      type: 'ashby', slug: 'atlan',  enabled: true, pollEveryMinutes: 2 },
  // ---- Adzuna (job search engine, India; free API key needed) ----
  // Free tier limit: 250 calls/day, 1000/week, 2500/month. 4 searches every
  // 80 min = 72 calls/day (~2230/month), so keep pollEveryMinutes >= 80.
  { company: 'Adzuna', type: 'adzuna', where: 'Hyderabad', what: '', enabled: true, pollEveryMinutes: 80 },
  { company: 'Adzuna', type: 'adzuna', where: 'Bangalore', what: '', enabled: true, pollEveryMinutes: 80 },
  { company: 'Adzuna', type: 'adzuna', where: 'Chennai',   what: '', enabled: true, pollEveryMinutes: 80 },
  { company: 'Adzuna', type: 'adzuna', where: 'India',     what: 'remote', enabled: true, pollEveryMinutes: 80 },
];

// Adzuna keyword search (matches ANY word). Role filtering happens later.
const ADZUNA_WHAT_OR = 'software developer python django backend analyst fresher graduate trainee machine learning data';

const URL_BUILDERS = {
  greenhouse: (s) => 'https://boards-api.greenhouse.io/v1/boards/' + s.slug + '/jobs',
  lever: (s) => 'https://api.lever.co/v0/postings/' + s.slug + '?mode=json',
  ashby: (s) => 'https://api.ashbyhq.com/posting-api/job-board/' + s.slug,
  // API keys are NOT here: they are added by the Adzuna credential.
  // Search params (where / what / what_or) are sent by the Fetch Adzuna Jobs node.
  adzuna: (s) => 'https://api.adzuna.com/v1/api/jobs/in/search/1',
};

// Throttle: a source with pollEveryMinutes = N only runs on every Nth minute.
const minute = Math.floor(Date.now() / 60000);

return SOURCES
  .filter((s) => s.enabled !== false && URL_BUILDERS[s.type])
  .filter((s) => minute % Math.max(1, s.pollEveryMinutes || 1) === 0)
  .map((s) => ({ json: { ...s, ...(s.type === 'adzuna' ? { what_or: ADZUNA_WHAT_OR } : {}), url: s.url || URL_BUILDERS[s.type](s) } }));

// =====================================================================
// NORMALIZE + PRE-FILTER (role & location) -- EDIT KEYWORDS HERE
// Converts every source's response into one common job shape, drops
// failed sources silently, and keeps only target roles in target cities.
// =====================================================================
const ROLE_PATTERNS = [
  /software engineer/i, /software developer/i, /software development engineer/i, /\bsde\b/i,
  /back[\s-]?end/i, /python/i, /django/i,
  /data analyst/i, /data scien/i,
  /machine learning/i, /\bml\b/i, /\bai\b/i, /ai\/ml/i, /artificial intelligence/i,
  /associate software/i, /graduate engineer trainee/i, /\bget\b/i, /graduate trainee/i,
  /analyst/i, /fresher/i, /new grad/i, /entry[\s-]level/i,
];
// Titles that signal seniority or a role type we do not want.
const EXCLUDE_TITLE = /senior|\bsr\b|\bsr\.|\blead\b|principal|\bstaff\b|manager|director|head of|architect|\bvp\b|vice president|\b(ii|iii|iv)\b|\b(sde|engineer|developer|analyst|scientist)[\s-]*(2|3|4)\b|\bintern(ship)?\b|intermediate|mid[\s-]level|\bl[2-9]\b/i;

const CITY_PATTERNS = [/hyderabad/i, /bangalore|bengaluru/i, /chennai/i];
const MAX_AGE_DAYS = 30; // ignore postings older than this (when a date exists)

function locationOk(locs, isRemote, countryIsIndia) {
  const text = locs.filter(Boolean).join(' | ');
  if (CITY_PATTERNS.some((p) => p.test(text))) return true;
  const remote = isRemote || /remote|work from home|wfh/i.test(text);
  const india = countryIsIndia || /india/i.test(text);
  return remote && india;
}
function roleOk(title) {
  return ROLE_PATTERNS.some((p) => p.test(title)) && !EXCLUDE_TITLE.test(title);
}
function fresh(posted) {
  if (!posted) return true;
  const t = new Date(posted).getTime();
  if (isNaN(t)) return true;
  return Date.now() - t <= MAX_AGE_DAYS * 86400000;
}

const out = [];
const seen = new Set();
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const d = items[i].json || {};
  let src;
  try { src = $('Job Sources Config').itemMatching(i).json; } catch (e) { src = null; }
  if (!src || d.error) continue; // failed source -> skip, others continue

  const jobs = [];
  try {
    if (src.type === 'greenhouse') {
      for (const j of d.jobs || []) {
        const offices = (j.offices || []).map((o) => o.name);
        jobs.push({
          title: j.title, location: (j.location && j.location.name) || '',
          locs: [(j.location && j.location.name) || ''].concat(offices),
          remote: false, india: false,
          posted_at: j.first_published || j.updated_at || '',
          job_url: j.absolute_url, description: '',
          detail_url: 'https://boards-api.greenhouse.io/v1/boards/' + src.slug + '/jobs/' + j.id,
        });
      }
    } else if (src.type === 'lever') {
      const list = Array.isArray(d) ? d : (d.id && d.text ? [d] : []);
      for (const j of list) {
        const c = j.categories || {};
        const lists = (j.lists || []).map((l) => (l.text || '') + ': ' + String(l.content || '')).join(' ');
        jobs.push({
          title: j.text, location: c.location || '',
          locs: [c.location || ''].concat(c.allLocations || []),
          remote: j.workplaceType === 'remote', india: j.country === 'IN',
          posted_at: j.createdAt ? new Date(j.createdAt).toISOString() : '',
          job_url: j.applyUrl || j.hostedUrl,
          description: (j.descriptionPlain || '') + ' ' + lists + ' ' + (j.additionalPlain || ''),
          detail_url: '',
        });
      }
    } else if (src.type === 'adzuna') {
      for (const j of d.results || []) {
        const area = (j.location && j.location.area) || [];
        const disp = (j.location && j.location.display_name) || '';
        // Strip tracking params so the same ad always has the same URL (dedupe key)
        const url = String(j.redirect_url || '').split('?')[0];
        jobs.push({
          title: j.title, location: disp,
          locs: [disp].concat(area),
          remote: /remote|work from home|wfh/i.test((j.title || '') + ' ' + (j.description || '')),
          india: true,
          posted_at: j.created || '',
          job_url: url,
          description: j.description || '', detail_url: '',
          company: (j.company && j.company.display_name) || '',
        });
      }
    } else if (src.type === 'ashby') {
      for (const j of d.jobs || []) {
        if (j.isListed === false) continue;
        const sec = (j.secondaryLocations || []).map((s) => (typeof s === 'string' ? s : s.location));
        const country = j.address && j.address.postalAddress ? j.address.postalAddress.addressCountry : '';
        jobs.push({
          title: j.title, location: j.location || '',
          locs: [j.location || ''].concat(sec),
          remote: !!j.isRemote || j.workplaceType === 'Remote', india: /india/i.test(country || ''),
          posted_at: j.publishedAt || '',
          job_url: j.applyUrl || j.jobUrl,
          description: j.descriptionPlain || '', detail_url: '',
        });
      }
    }
  } catch (e) {
    continue; // malformed response from one source must not break the run
  }

  for (const j of jobs) {
    if (!j.job_url || !j.title) continue;
    if (seen.has(j.job_url)) continue; // in-run duplicate guard
    if (!roleOk(j.title)) continue;
    if (!locationOk(j.locs, j.remote, j.india)) continue;
    if (!fresh(j.posted_at)) continue;
    seen.add(j.job_url);
    let location = j.location;
    // If the primary location is elsewhere, show the matching target city instead
    if (!CITY_PATTERNS.some((p) => p.test(location))) {
      const hit = j.locs.find((l) => l && CITY_PATTERNS.some((p) => p.test(l)));
      if (hit) location = hit;
    }
    if (!location || (j.remote && !CITY_PATTERNS.some((p) => p.test(location)))) {
      location = (location ? location + ' ' : '') + (j.remote ? '(Remote India)' : '');
    }
    out.push({
      json: {
        job_url: j.job_url,
        title: j.title,
        company: j.company || src.company,
        location: location.trim(),
        posted_at: j.posted_at,
        description: j.description,
        detail_url: j.detail_url,
        needs_details: !!j.detail_url,
        source: src.type === 'adzuna' ? 'Jobs by Adzuna' : src.company + ' careers (' + src.type + ')',
      },
    });
  }
}
return out;

// Re-attach the job record and add the full description fetched from the
// Greenhouse job-detail endpoint. If the detail call failed, keep the job
// with an empty description (it is still evaluated, not lost).
const job = $('Needs Job Details?').item.json;
const content = $json && !$json.error ? ($json.content || '') : '';
return { json: { ...job, description: content } };

// =====================================================================
// EXPERIENCE FILTER + TELEGRAM MESSAGE BUILDER
// Rejects jobs whose description requires more than MAX_YEARS of
// experience, labels the experience, builds a short summary and the
// Telegram message (HTML-escaped).
// =====================================================================
const MAX_YEARS = 1;
const SUMMARY_CHARS = 300;
const FRESHER_RE = /fresher|entry[\s-]level|new grad|graduate engineer trainee|2026 (grad|batch|pass)|batch of 2026|class of 2026|0\s*(-|–|to)\s*1\s*(years?|yrs?)|no (prior )?experience required/i;

function toText(html) {
  return String(html || '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-z#0-9]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function experienceMentions(text) {
  const re = /(\d{1,2})\s*(?:\+|plus)?\s*(?:(?:-|–|to)\s*(\d{1,2}))?\s*\+?\s*(?:years?|yrs?)/gi;
  const found = [];
  let m;
  while ((m = re.exec(text)) !== null) {
    const ctx = text.slice(Math.max(0, m.index - 80), m.index + m[0].length + 80).toLowerCase();
    if (!/experience|exp\b|work(ing)?\b|industry/.test(ctx)) continue;
    const lo = parseInt(m[1], 10);
    if (lo <= 30) found.push({ lo: lo, raw: m[0].trim() });
  }
  return found;
}
function esc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function summarize(text) {
  if (!text) return 'No description available - open the link for details.';
  if (text.length <= SUMMARY_CHARS) return text;
  const cut = text.slice(0, SUMMARY_CHARS);
  return cut.slice(0, cut.lastIndexOf(' ') > 0 ? cut.lastIndexOf(' ') : SUMMARY_CHARS) + '...';
}

return $input.all().map((item) => {
  const job = item.json;
  const text = toText(job.description);
  const mentions = experienceMentions(text);
  const required = mentions.length ? Math.max.apply(null, mentions.map((x) => x.lo)) : null;
  const isFresher = FRESHER_RE.test(job.title + ' ' + text);

  let experience = 'Not specified (no senior requirement found)';
  if (isFresher) experience = 'Fresher / Entry level (0-1 yrs)';
  if (required !== null && !isFresher) {
    const best = mentions.find((x) => x.lo === required);
    experience = best ? best.raw : required + ' years';
  }
  const matched = required === null || required <= MAX_YEARS;

  const summary = summarize(text);
  const message =
    '🔥 NEW JOB\n\n' +
    '💼 ' + esc(job.title) + '\n' +
    '🏢 ' + esc(job.company) + '\n' +
    '📍 ' + esc(job.location) + '\n' +
    '🎓 Experience: ' + esc(experience) + '\n\n' +
    '📝 ' + esc(summary) + '\n\n' +
    '🔗 Apply:\n' + esc(job.job_url) + '\n\n' +
    'Source: ' + esc(job.source);

  return {
    json: {
      job_url: job.job_url,
      title: job.title,
      company: job.company,
      location: job.location,
      posted_at: job.posted_at,
      experience: experience,
      summary: summary,
      source: job.source,
      matched: matched,
      reject_reason: matched ? '' : 'requires ' + required + '+ years',
      telegram_message: message,
    },
  };
});
